import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';
import { BaseConnector } from '../../src/services/connectors/baseConnector';
import { OERConnector } from '../../src/services/connectors/oerConnector';
import { CurriculumWebConnector } from '../../src/services/connectors/curriculumWebConnector';
import { EducationWebConnector } from '../../src/services/connectors/educationWebConnector';
import { SearchParams } from '../../src/services/activityDiscoveryService';

// Mock global fetch
global.fetch = jest.fn();

// Create a concrete implementation of BaseConnector for testing
class TestConnector extends BaseConnector {
  constructor() {
    super('test');
  }

  async search(params: SearchParams) {
    return [
      this.transformToExternalActivity({
        externalId: 'test-1',
        title: 'Test Activity',
        description: 'A test activity',
      }, {
        externalId: 'test-1',
        url: 'https://test.com/activity/1',
        title: 'Test Activity',
        description: 'A test activity',
      }),
    ];
  }

  async getActivityDetails(externalId: string) {
    if (externalId === 'test-1') {
      return this.transformToExternalActivity({
        externalId: 'test-1',
        title: 'Test Activity Detailed',
        description: 'A detailed test activity',
      }, {
        externalId: 'test-1',
        url: 'https://test.com/activity/1',
        title: 'Test Activity Detailed',
        description: 'A detailed test activity',
      });
    }
    return null;
  }
}

describe('BaseConnector', () => {
  let connector: TestConnector;

  beforeEach(() => {
    connector = new TestConnector();
    jest.clearAllMocks();
  });

  describe('transformToExternalActivity', () => {
    it('should transform data with defaults', () => {
      const result = connector['transformToExternalActivity']({}, {
        externalId: 'test-123',
        url: 'https://example.com/test',
        title: 'Test Activity',
      });

      expect(result).toEqual({
        source: 'test',
        externalId: 'test-123',
        url: 'https://example.com/test',
        title: 'Test Activity',
        description: null,
        thumbnailUrl: null,
        duration: null,
        activityType: 'worksheet',
        gradeMin: 1,
        gradeMax: 1,
        subject: 'general',
        language: 'en',
        materials: [],
        technology: null,
        groupSize: null,
        sourceRating: null,
        sourceReviews: null,
        internalRating: null,
        internalReviews: null,
        curriculumTags: [],
        learningGoals: null,
        isFree: true,
        price: null,
        license: null,
        lastVerified: expect.any(Date),
        isActive: true,
      });
    });

    it('should override defaults with provided values', () => {
      const result = connector['transformToExternalActivity']({}, {
        externalId: 'test-123',
        url: 'https://example.com/test',
        title: 'Custom Activity',
        activityType: 'game',
        gradeMin: 3,
        gradeMax: 5,
        isFree: false,
        price: 9.99,
      });

      expect(result.title).toBe('Custom Activity');
      expect(result.activityType).toBe('game');
      expect(result.gradeMin).toBe(3);
      expect(result.gradeMax).toBe(5);
      expect(result.isFree).toBe(false);
      expect(result.price).toBe(9.99);
    });
  });

  describe('parseDuration', () => {
    it('should parse ISO 8601 duration formats', () => {
      expect(connector['parseDuration']('PT15M')).toBe(15);
      expect(connector['parseDuration']('PT1H')).toBe(60);
      expect(connector['parseDuration']('PT1H30M')).toBe(90);
      expect(connector['parseDuration']('PT2H15M30S')).toBe(136); // 2:15:30 = 135.5 minutes, rounded up to 136
    });

    it('should parse text duration formats', () => {
      expect(connector['parseDuration']('15 minutes')).toBe(15);
      expect(connector['parseDuration']('2 hours')).toBe(120);
      expect(connector['parseDuration']('30 mins')).toBe(30);
      expect(connector['parseDuration']('1 hour')).toBe(60);
    });

    it('should return null for invalid formats', () => {
      expect(connector['parseDuration']('')).toBeNull();
      expect(connector['parseDuration']('invalid')).toBeNull();
      expect(connector['parseDuration']('PT')).toBe(0); // Actually returns 0 for empty PT
    });

    it('should handle edge cases', () => {
      expect(connector['parseDuration']('PT0M')).toBe(0);
      expect(connector['parseDuration']('PT59S')).toBe(1); // Rounds up to 1 minute
    });
  });

  describe('parseGradeRange', () => {
    it('should parse single grades', () => {
      expect(connector['parseGradeRange']('Grade 3')).toEqual({ min: 3, max: 3 });
      expect(connector['parseGradeRange']('3rd Grade')).toEqual({ min: 3, max: 3 });
      expect(connector['parseGradeRange']('Gr. 5')).toEqual({ min: 5, max: 5 });
    });

    it('should parse grade ranges', () => {
      expect(connector['parseGradeRange']('Grades 1-3')).toEqual({ min: 1, max: 3 });
      expect(connector['parseGradeRange']('K-2')).toEqual({ min: 0, max: 2 });
      expect(connector['parseGradeRange']('3-5')).toEqual({ min: 3, max: 5 });
    });

    it('should handle kindergarten', () => {
      expect(connector['parseGradeRange']('K')).toEqual({ min: 0, max: 0 });
      expect(connector['parseGradeRange']('Kindergarten')).toEqual({ min: 0, max: 0 });
    });

    it('should return default for invalid input', () => {
      expect(connector['parseGradeRange']('')).toEqual({ min: 1, max: 1 });
      expect(connector['parseGradeRange']('invalid')).toEqual({ min: 1, max: 1 });
    });

    it('should handle multiple numbers correctly', () => {
      expect(connector['parseGradeRange']('Grades 5, 3, 7')).toEqual({ min: 3, max: 7 });
    });
  });

  describe('normalizeSubject', () => {
    it('should normalize common subject variations', () => {
      expect(connector['normalizeSubject']('Mathematics')).toBe('math');
      expect(connector['normalizeSubject']('Maths')).toBe('math');
      expect(connector['normalizeSubject']('French')).toBe('francais');
      expect(connector['normalizeSubject']('French Immersion')).toBe('francais');
      expect(connector['normalizeSubject']('Language Arts')).toBe('english');
      expect(connector['normalizeSubject']('ELA')).toBe('english');
      expect(connector['normalizeSubject']('Social Studies')).toBe('social-studies');
      expect(connector['normalizeSubject']('Physical Education')).toBe('physical-education');
      expect(connector['normalizeSubject']('Phys Ed')).toBe('physical-education');
      expect(connector['normalizeSubject']('PE')).toBe('physical-education');
    });

    it('should handle case insensitive input', () => {
      expect(connector['normalizeSubject']('MATHEMATICS')).toBe('math');
      expect(connector['normalizeSubject']('language arts')).toBe('english');
      expect(connector['normalizeSubject']('Social STUDIES')).toBe('social-studies');
    });

    it('should return original for unknown subjects', () => {
      expect(connector['normalizeSubject']('Unknown Subject')).toBe('unknown subject');
      expect(connector['normalizeSubject']('Custom')).toBe('custom');
    });

    it('should trim whitespace', () => {
      expect(connector['normalizeSubject']('  Mathematics  ')).toBe('math');
    });
  });

  describe('inferActivityType', () => {
    it('should infer type from title and description', () => {
      expect(connector['inferActivityType']({
        title: 'Math Video Tutorial',
        description: 'Watch this educational video'
      })).toBe('video');

      expect(connector['inferActivityType']({
        title: 'Addition Worksheet',
        description: 'Printable practice sheet'
      })).toBe('worksheet');

      expect(connector['inferActivityType']({
        title: 'Interactive Math Game',
        description: 'Fun learning game'
      })).toBe('game');

      expect(connector['inferActivityType']({
        title: 'Science Experiment',
        description: 'Hands-on lab activity'
      })).toBe('experiment');

      expect(connector['inferActivityType']({
        title: 'Hands-on Activity',
        description: 'Use manipulatives'
      })).toBe('handson');
    });

    it('should default to worksheet for unknown types', () => {
      expect(connector['inferActivityType']({
        title: 'Unknown Activity',
        description: 'No clear type indicators'
      })).toBe('worksheet');
    });

    it('should handle missing data', () => {
      expect(connector['inferActivityType']({})).toBe('worksheet');
    });
  });

  describe('extractMaterials', () => {
    it('should extract materials from structured text', () => {
      const text = 'Materials needed: pencil, paper, scissors, glue';
      const materials = connector['extractMaterials'](text);
      
      expect(materials).toContain('pencil');
      expect(materials).toContain('paper');
      expect(materials).toContain('scissors');
      expect(materials).toContain('glue');
    });

    it('should extract from different patterns', () => {
      const text1 = 'You will need: markers, crayons';
      const text2 = 'Supplies: dice, cards';
      const text3 = 'Required materials: calculator, ruler';
      
      expect(connector['extractMaterials'](text1)).toEqual(['markers', 'crayons']);
      expect(connector['extractMaterials'](text2)).toEqual(['dice', 'cards']);
      expect(connector['extractMaterials'](text3)).toEqual(['calculator', 'ruler']);
    });

    it('should find specific materials mentioned in text', () => {
      const text = 'Students should bring their pencil and use the whiteboard. A computer may also be helpful.';
      const materials = connector['extractMaterials'](text);
      
      expect(materials).toContain('pencil');
      expect(materials).toContain('whiteboard');
      expect(materials).toContain('computer');
    });

    it('should remove duplicates', () => {
      const text = 'Materials: pencil, paper, pencil, markers';
      const materials = connector['extractMaterials'](text);
      
      expect(materials.filter(m => m === 'pencil')).toHaveLength(1);
    });

    it('should handle empty input', () => {
      expect(connector['extractMaterials']('')).toEqual([]);
      expect(connector['extractMaterials']('No materials mentioned')).toEqual([]);
    });

    it('should filter out very long items', () => {
      const text = 'Materials: pencil, ' + 'very-long-item-name-that-exceeds-reasonable-length'.repeat(3);
      const materials = connector['extractMaterials'](text);
      
      expect(materials).toContain('pencil');
      expect(materials.some(m => m.length > 50)).toBe(false);
    });
  });

  describe('fetchWithTimeout', () => {
    beforeEach(() => {
      jest.useFakeTimers();
    });

    afterEach(() => {
      jest.useRealTimers();
    });

    it('should fetch successfully within timeout', async () => {
      const mockResponse = new Response('success', { status: 200 });
      (global.fetch as jest.Mock).mockResolvedValue(mockResponse);

      const promise = connector['fetchWithTimeout']('https://example.com', {}, 5000);
      
      const result = await promise;
      
      expect(result).toBe(mockResponse);
      expect(global.fetch).toHaveBeenCalledWith('https://example.com', {
        signal: expect.any(AbortSignal),
      });
    });

    it('should timeout after specified duration', async () => {
      (global.fetch as jest.Mock).mockImplementation(() => new Promise(() => {})); // Never resolves

      const promise = connector['fetchWithTimeout']('https://example.com', {}, 1000);
      
      // Fast-forward time to trigger timeout
      jest.advanceTimersByTime(1000);

      await expect(promise).rejects.toThrow('Request timeout after 1000ms');
    }, 10000);

    it('should handle fetch errors', async () => {
      (global.fetch as jest.Mock).mockRejectedValue(new Error('Network error'));

      await expect(
        connector['fetchWithTimeout']('https://example.com', {}, 5000)
      ).rejects.toThrow('Network error');
    });

    it('should clear timeout on successful fetch', async () => {
      const mockResponse = new Response('success', { status: 200 });
      (global.fetch as jest.Mock).mockResolvedValue(mockResponse);

      const clearTimeoutSpy = jest.spyOn(global, 'clearTimeout');
      
      await connector['fetchWithTimeout']('https://example.com', {}, 5000);
      
      expect(clearTimeoutSpy).toHaveBeenCalled();
    });
  });

  describe('fetchWithRetryAndTimeout', () => {
    beforeEach(() => {
      jest.useFakeTimers();
    });

    afterEach(() => {
      jest.useRealTimers();
    });

    it('should return response text on success', async () => {
      const mockResponse = new Response('success content', { status: 200 });
      mockResponse.text = jest.fn().mockResolvedValue('success content');
      (global.fetch as jest.Mock).mockResolvedValue(mockResponse);

      const result = await connector['fetchWithRetryAndTimeout']('https://example.com');
      
      expect(result).toBe('success content');
    });

    it('should retry on failure', async () => {
      const mockErrorResponse = new Response('error', { status: 500, statusText: 'Internal Server Error' });
      const mockSuccessResponse = new Response('success', { status: 200 });
      mockSuccessResponse.text = jest.fn().mockResolvedValue('success content');
      
      (global.fetch as jest.Mock)
        .mockResolvedValueOnce(mockErrorResponse) // First attempt fails
        .mockResolvedValueOnce(mockSuccessResponse); // Second attempt succeeds

      // Mock delay to prevent actual waiting
      const delaySpy = jest.spyOn(connector as any, 'delay').mockResolvedValue(undefined);

      const result = await connector['fetchWithRetryAndTimeout']('https://example.com', {}, 2);
      
      expect(result).toBe('success content');
      expect(global.fetch).toHaveBeenCalledTimes(2);
      expect(delaySpy).toHaveBeenCalled();
    });

    it('should handle rate limiting with increased delay', async () => {
      const mockRateLimitResponse = new Response('rate limited', { status: 429 });
      const mockSuccessResponse = new Response('success', { status: 200 });
      mockSuccessResponse.text = jest.fn().mockResolvedValue('success content');
      
      (global.fetch as jest.Mock)
        .mockResolvedValueOnce(mockRateLimitResponse)
        .mockResolvedValueOnce(mockSuccessResponse);

      const delaySpy = jest.spyOn(connector as any, 'delay').mockResolvedValue(undefined);

      const result = await connector['fetchWithRetryAndTimeout']('https://example.com', {}, 2, 30000, 1000);
      
      expect(result).toBe('success content');
      expect(delaySpy).toHaveBeenCalledWith(2000); // 2x base delay for rate limiting
    });

    it('should return null after all retries fail', async () => {
      const mockErrorResponse = new Response('error', { status: 500 });
      (global.fetch as jest.Mock).mockResolvedValue(mockErrorResponse);

      const delaySpy = jest.spyOn(connector as any, 'delay').mockResolvedValue(undefined);

      const result = await connector['fetchWithRetryAndTimeout']('https://example.com', {}, 3);
      
      expect(result).toBeNull();
      expect(global.fetch).toHaveBeenCalledTimes(3);
      expect(delaySpy).toHaveBeenCalledTimes(2); // 2 delays between 3 attempts
    });

    it('should handle network errors', async () => {
      (global.fetch as jest.Mock).mockRejectedValue(new Error('Network error'));

      const delaySpy = jest.spyOn(connector as any, 'delay').mockResolvedValue(undefined);

      const result = await connector['fetchWithRetryAndTimeout']('https://example.com', {}, 2);
      
      expect(result).toBeNull();
      expect(global.fetch).toHaveBeenCalledTimes(2);
      expect(delaySpy).toHaveBeenCalled();
    });
  });

  describe('delay', () => {
    beforeEach(() => {
      jest.useFakeTimers();
    });

    afterEach(() => {
      jest.useRealTimers();
    });

    it('should delay for specified milliseconds', async () => {
      const promise = connector['delay'](1000);
      
      expect(setTimeout).toHaveBeenCalledWith(expect.any(Function), 1000);
      
      jest.advanceTimersByTime(1000);
      
      await expect(promise).resolves.toBeUndefined();
    });
  });

  describe('checkAvailability', () => {
    it('should return true when activity details are found', async () => {
      const isAvailable = await connector.checkAvailability('test-1');
      expect(isAvailable).toBe(true);
    });

    it('should return false when activity details are not found', async () => {
      const isAvailable = await connector.checkAvailability('non-existent');
      expect(isAvailable).toBe(false);
    });
  });

  describe('search and getActivityDetails', () => {
    it('should search for activities', async () => {
      const results = await connector.search({ query: 'test' });
      
      expect(results).toHaveLength(1);
      expect(results[0].externalId).toBe('test-1');
      expect(results[0].title).toBe('Test Activity');
    });

    it('should get activity details', async () => {
      const activity = await connector.getActivityDetails('test-1');
      
      expect(activity).toBeDefined();
      expect(activity?.externalId).toBe('test-1');
      expect(activity?.title).toBe('Test Activity Detailed');
    });

    it('should return null for non-existent activity', async () => {
      const activity = await connector.getActivityDetails('non-existent');
      expect(activity).toBeNull();
    });
  });
});

